import { useState, useCallback, useRef } from 'react';
import { VectorElement, Point, VectorElementType } from '../types';

export const useVectorEditor = (initialElements: VectorElement[] = []) => {
  const [elements, setElements] = useState<VectorElement[]>(initialElements);
  const [selection, setSelection] = useState<string[]>([]);
  const [activeTool, setActiveTool] = useState<VectorElementType | 'select'>('select');
  const [isDrawing, setIsDrawing] = useState(false);
  const [currentPoints, setCurrentPoints] = useState<Point[]>([]);

  const addElement = useCallback((element: VectorElement) => {
    setElements(prev => [...prev, element]);
  }, []);

  const updateElement = useCallback((id: string, updates: Partial<VectorElement>) => {
    setElements(prev => prev.map(el => el.id === id ? { ...el, ...updates } : el));
  }, []);

  const deleteElements = useCallback((ids: string[]) => {
    setElements(prev => prev.filter(el => !ids.includes(el.id)));
    setSelection([]);
  }, []);

  const handlePointerDown = useCallback((pos: Point, e: React.PointerEvent) => {
    if (activeTool === 'select') {
      // Basic selection logic handled by element onClick usually
      return;
    }

    setIsDrawing(true);
    if (activeTool === 'path') {
      setCurrentPoints([pos]);
    } else {
      // Shape start
      setCurrentPoints([pos, pos]);
    }
  }, [activeTool]);

  const handlePointerMove = useCallback((pos: Point) => {
    if (!isDrawing) return;

    if (activeTool === 'path') {
      setCurrentPoints(prev => [...prev, pos]);
    } else {
      setCurrentPoints(prev => [prev[0], pos]);
    }
  }, [isDrawing, activeTool]);

  const handlePointerUp = useCallback(() => {
    if (!isDrawing) return;

    const id = crypto.randomUUID();
    const start = currentPoints[0];
    const end = currentPoints[currentPoints.length - 1];

    let newElement: VectorElement | null = null;

    if (activeTool === 'path' && currentPoints.length > 2) {
      newElement = {
        id, type: 'path', points: [...currentPoints], 
        x: 0, y: 0, width: 0, height: 0, 
        fill: 'none', stroke: '#5546fe', strokeWidth: 4, 
        opacity: 1, rotation: 0, isVisible: true
      };
    } else if (activeTool === 'rect') {
      const x = Math.min(start.x, end.x);
      const y = Math.min(start.y, end.y);
      const w = Math.abs(start.x - end.x);
      const h = Math.abs(start.y - end.y);
      if (w > 5 && h > 5) {
        newElement = {
          id, type: 'rect', points: [], 
          x, y, width: w, height: h, 
          fill: '#5546fe22', stroke: '#5546fe', strokeWidth: 2, 
          opacity: 1, rotation: 0, isVisible: true
        };
      }
    } else if (activeTool === 'circle') {
      const radius = Math.hypot(end.x - start.x, end.y - start.y);
      if (radius > 5) {
        newElement = {
          id, type: 'circle', points: [], 
          x: start.x, y: start.y, width: radius * 2, height: radius * 2, 
          fill: '#5546fe22', stroke: '#5546fe', strokeWidth: 2, 
          opacity: 1, rotation: 0, isVisible: true
        };
      }
    }

    if (newElement) {
      setElements(prev => [...prev, newElement!]);
      setSelection([id]);
    }

    setIsDrawing(false);
    setCurrentPoints([]);
  }, [isDrawing, activeTool, currentPoints]);

  return {
    elements,
    setElements,
    selection,
    setSelection,
    activeTool,
    setActiveTool,
    isDrawing,
    currentPoints,
    handlePointerDown,
    handlePointerMove,
    handlePointerUp,
    updateElement,
    deleteElements
  };
};

import React, { useState, useRef, useEffect, useMemo } from 'react';
