    XIcon, SparklesIcon, ZapIcon, PlusIcon, TrashIcon, 
    CursorIcon, PenIcon, SquareIcon, CircleIcon, 
    MaximizeIcon, RefreshIcon, ChevronLeftIcon, BoxIcon, 
    PaletteIcon, SlidersIcon, WandIcon, DownloadIcon, CheckIcon, UndoIcon, TargetIcon, ScanIcon, ImageSelectionIcon
} from './Icons';
