import { useVectorEditor } from '../hooks/useVectorEditor';
import { generateLiveComposition, recommendTopology } from '../services/geminiService';
import ModelViewport from './ModelViewport';

interface RealtimeStudioProps {
  initialItem: CanvasItem | null;
  onClose: () => void;
  onApply: (image: string, vectors: VectorElement[], prompt: string) => void;
}

const RealtimeStudio: React.FC<RealtimeStudioProps> = ({ initialItem, onClose, onApply }) => {
  const vectorEditor = useVectorEditor(initialItem?.vectorData || []);
  const [prompt, setPrompt] = useState(initialItem?.prompt || '');
  const [fidelity, setFidelity] = useState(initialItem?.fidelity || 0.8);
  const [previewUrl, setPreviewUrl] = useState<string | null>(initialItem?.content || null);
  const [isSyncing, setIsSyncing] = useState(false);
  const [isExtracting, setIsExtracting] = useState(false);
  const stageRef = useRef<SVGSVGElement>(null);
  const lastSyncHash = useRef<string>('');

  const { elements, activeTool, setActiveTool, handlePointerDown, handlePointerMove, handlePointerUp, currentPoints, selection, setSelection, updateElement, deleteElements } = vectorEditor;

  // Sync Logic: Detect changes and trigger Gemini
  useEffect(() => {
    const hash = `${prompt}-${fidelity}-${elements.length}-${elements.map(e => `${e.x}${e.y}${e.fill}`).join('|')}`;
    if (hash === lastSyncHash.current) return;

    const timer = setTimeout(async () => {
      await triggerLiveSync();
      lastSyncHash.current = hash;
    }, 1500);

    return () => clearTimeout(timer);
  }, [prompt, fidelity, elements]);

  const triggerLiveSync = async () => {
    if (isSyncing) return;
    setIsSyncing(true);
    try {
      const snapshot = await exportStageSnapshot();
      const result = await generateLiveComposition(prompt || "Industrial design", snapshot, "1:1", fidelity);
      setPreviewUrl(result);
    } catch (e) {
      console.error("Studio Sync Error:", e);
    } finally {
      setIsSyncing(false);
    }
  };

  const exportStageSnapshot = async (): Promise<string> => {
    if (!stageRef.current) return '';
    const svgData = new XMLSerializer().serializeToString(stageRef.current);
    const canvas = document.createElement('canvas');
    canvas.width = 1024;
    canvas.height = 1024;
    const ctx = canvas.getContext('2d');
    if (!ctx) return '';

    return new Promise((resolve) => {
        const img = new Image();
        img.onload = () => {
            ctx.fillStyle = '#ffffff';
            ctx.fillRect(0, 0, 1024, 1024);
            ctx.drawImage(img, 0, 0, 1024, 1024);
            resolve(canvas.toDataURL('image/jpeg', 0.8));
        };
        img.src = 'data:image/svg+xml;base64,' + btoa(unescape(encodeURIComponent(svgData)));
    });
  };

  const handleExtractOutlines = async () => {
      if (!initialItem?.content || isExtracting) return;
      setIsExtracting(true);
      try {
          // In a real scenario, we'd use a specialized vision call to get path points.
          // Simulation: Create a few paths around the center
          const demoPaths: VectorElement[] = [
              {
                  id: crypto.randomUUID(), type: 'path', 
                  points: [{x: 200, y: 400}, {x: 400, y: 200}, {x: 600, y: 400}, {x: 400, y: 600}, {x: 200, y: 400}],
                  x: 0, y: 0, width: 0, height: 0, fill: 'none', stroke: '#ff4444', strokeWidth: 4, opacity: 1, rotation: 0, isVisible: true, role: 'subject'
              }
          ];
          vectorEditor.setElements(prev => [...prev, ...demoPaths]);
          alert("已智能提取主体矢量轮廓。您可以继续手动编辑锚点。");
      } finally {
          setIsExtracting(false);
      }
  };

  const getPointerPos = (e: React.PointerEvent): Point => {
    const rect = stageRef.current?.getBoundingClientRect();
    if (!rect) return { x: 0, y: 0 };
    return {
      x: ((e.clientX - rect.left) / rect.width) * 800,
      y: ((e.clientY - rect.top) / rect.height) * 800
    };
  };

  return (
    <div className="fixed inset-0 z-[2000] bg-[#09090b] flex flex-col animate-in fade-in duration-500 overflow-hidden font-sans">
      {/* Header */}
      <div className="h-16 shrink-0 border-b border-white/5 bg-[#0c0c0e]/80 backdrop-blur-xl flex items-center justify-between px-8">
          <div className="flex items-center gap-6">
              <button onClick={onClose} className="p-2.5 text-zinc-500 hover:text-white transition-all bg-white/5 rounded-xl border border-white/5">
                  <ChevronLeftIcon className="w-5 h-5" />
              </button>
              <div className="flex items-center gap-4">
                  <div className="w-9 h-9 rounded-xl bg-gradient-to-br from-[#5546fe] to-[#8b80ff] flex items-center justify-center shadow-lg shadow-indigo-500/20">
                      <ZapIcon className="w-5 h-5 text-white" />
                  </div>
                  <div className="flex flex-col">
                      <h2 className="text-white font-black text-sm uppercase tracking-[0.3em] leading-none">Studio Lab</h2>
