                  <span className="text-[10px] font-black text-zinc-400 uppercase tracking-widest">{isSyncing ? 'Synchronizing' : 'Live Ready'}</span>
              </div>
              <button 
                  onClick={() => previewUrl && onApply(previewUrl, elements, prompt)}
                  className="px-8 py-2.5 bg-indigo-600 hover:bg-indigo-500 text-white rounded-xl font-black text-[12px] uppercase tracking-[0.2em] transition-all shadow-xl active:scale-95"
