  // --- Live Studio Loop Implementation ---
  useEffect(() => {
    const studioStages = items.filter(it => it.type === ItemType.STUDIO && it.isLive);
    if (studioStages.length === 0) return;

    studioStages.forEach(stage => {
        const children = items.filter(it => 
            it.id !== stage.id && 
            it.x >= stage.x && it.x + it.width <= stage.x + stage.width &&
            it.y >= stage.y && it.y + it.height <= stage.y + stage.height
        );

        // Use a simple hash of children positions/ids/roles to detect change
        const childHash = children.map(c => `${c.id}-${Math.round(c.x)}-${Math.round(c.y)}-${c.content.slice(-10)}-${c.role}`).join('|');
        const prevHash = (stage as any)._lastChildHash;

        if (childHash !== prevHash) {
            // Something changed, trigger live update
            if (liveSyncTimerRef.current[stage.id]) window.clearTimeout(liveSyncTimerRef.current[stage.id]);
            liveSyncTimerRef.current[stage.id] = window.setTimeout(() => {
                handleLiveSync(stage.id, children);
                setItems(prev => prev.map(it => it.id === stage.id ? { ...it, _lastChildHash: childHash } as any : it));
            }, 1200); // 1.2s debounce for reactive feeling without hitting limits too hard
        }
    });
  }, [items]);

  const handleLiveSync = async (stageId: string, children: CanvasItem[]) => {
      const stage = items.find(it => it.id === stageId);
      if (!stage) return;

      // Double buffering start
      setItems(prev => prev.map(it => it.id === stageId ? { ...it, isLiveLoading: true } : it));

      try {
          // Render a mini snapshot of the stage area
          const snapshot = await createStageSnapshot(stage, children);
          const resultUrl = await generateLiveComposition(
              stage.prompt || "Professional ID design",
              snapshot,
              stage.aspectRatio || "1:1",
              stage.fidelity ?? 0.8
          );

          setItems(prev => prev.map(it => it.id === stageId ? { ...it, liveResultContent: resultUrl, isLiveLoading: false } : it));
      } catch (e) {
          console.error("Live Sync Failed:", e);
          setItems(prev => prev.map(it => it.id === stageId ? { ...it, isLiveLoading: false } : it));
      }
  };

  const createStageSnapshot = async (stage: CanvasItem, children: CanvasItem[]): Promise<string> => {
      const canvas = document.createElement('canvas');
      canvas.width = 1024;
      canvas.height = 1024;
      const ctx = canvas.getContext('2d');
      if (!ctx) return '';

      ctx.fillStyle = '#ffffff';
      ctx.fillRect(0, 0, 1024, 1024);

      const drawItem = (it: CanvasItem) => {
          const relX = (it.x - stage.x) / stage.width * 1024;
          const relY = (it.y - stage.y) / stage.height * 1024;
          const relW = it.width / stage.width * 1024;
          const relH = it.height / stage.height * 1024;

          if (it.type === ItemType.SHAPE) {
              ctx.fillStyle = it.textColor || '#000';
              if (it.content === 'circle') {
                  ctx.beginPath();
                  ctx.arc(relX + relW/2, relY + relH/2, Math.min(relW, relH)/2, 0, Math.PI * 2);
                  ctx.fill();
              } else {
                  ctx.fillRect(relX, relY, relW, relH);
              }
          } else if (it.type === ItemType.IMAGE && it.content) {
              return new Promise((resolve) => {
                  const img = new Image();
                  img.onload = () => {
                      ctx.drawImage(img, relX, relY, relW, relH);
                      resolve(null);
                  };
                  img.src = it.content;
              });
          }
          return Promise.resolve();
      };

      await Promise.all(children.map(drawItem));
      return canvas.toDataURL('image/jpeg', 0.8);
  };

  useEffect(() => {
    if (selectedItem?.type === ItemType.TEXT) {
