  const createStageSnapshot = async (stage: CanvasItem, children: CanvasItem[]): Promise<string> => {
      const canvas = document.createElement('canvas');
      canvas.width = 1024;
      canvas.height = 1024;
      const ctx = canvas.getContext('2d');
      if (!ctx) return '';

      ctx.fillStyle = '#ffffff';
      ctx.fillRect(0, 0, 1024, 1024);

      const drawItem = (it: CanvasItem) => {
          const relX = (it.x - stage.x) / stage.width * 1024;
          const relY = (it.y - stage.y) / stage.height * 1024;
          const relW = it.width / stage.width * 1024;
          const relH = it.height / stage.height * 1024;

          if (it.type === ItemType.SHAPE) {
              ctx.fillStyle = it.textColor || '#000';
              if (it.content === 'circle') {
                  ctx.beginPath();
                  ctx.arc(relX + relW/2, relY + relH/2, Math.min(relW, relH)/2, 0, Math.PI * 2);
                  ctx.fill();
              } else {
                  ctx.fillRect(relX, relY, relW, relH);
              }
          } else if (it.type === ItemType.IMAGE && it.content) {
              return new Promise((resolve) => {
                  const img = new Image();
                  img.onload = () => {
                      ctx.drawImage(img, relX, relY, relW, relH);
                      resolve(null);
                  };
                  img.src = it.content;
              });
          }
          return Promise.resolve();
      };

      await Promise.all(children.map(drawItem));
      return canvas.toDataURL('image/jpeg', 0.8);
  };

