p => p.id === pid); if (point) chatRef.current?.appendMovementDescription(iid, item.content, point.label, from, to); } }} isTextMode={editSubMode === 'text'} showGrid={showGrid} onZoomToFit={zoomToFit} onCaptureRegion={handleCaptureRegion} onFloatingAction={handleFloatingAction} expressionState={expressionState} setExpressionState={setExpressionState} inferenceState={inferenceState} setInferenceState={setInferenceState} topologyState={topologyState} setTopologyState={setTopologyState} currentEvolutionLevel={currentEvolutionLevel} captureState={captureState} onExitToolMode={() => setTool('select')} activePartId={activePartId} onPartSelect={setActivePartId} onCameraChange={(id, s) => handleUpdateItem(id, { spatialConfig: s })} onLoadParts={(id, p) => handleUpdateItem(id, { partList: p })} />
      </div>

      {studioOpen && (
          <RealtimeStudio 
